import{_ as o,c as r,o as e,aj as a}from"./chunks/framework.C2N4vG9O.js";const p=JSON.parse('{"title":"研发工具导览","description":"Torch-RecHub 研发工具概述","frontmatter":{"title":"研发工具导览","description":"Torch-RecHub 研发工具概述"},"headers":[],"relativePath":"zh/tools/intro.md","filePath":"zh/tools/intro.md"}'),l={name:"zh/tools/intro.md"};function n(c,t,s,i,h,_){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="研发工具导览" tabindex="-1">研发工具导览 <a class="header-anchor" href="#研发工具导览" aria-label="Permalink to “研发工具导览”">​</a></h1><p>在排序、召回和多任务示例里，给 <code>fit()</code> 传入 <code>log_interval=1</code>，进度条就会显示每个 batch 的损失和学习率。只想确认模型有没有开始学习，看这里就够了。</p><p>如果要回看训练结果，可以按问题找工具。</p><ul><li><strong>哪一轮的模型值得保存？</strong> 用验证集监控 AUC 或损失。训练器会保留最佳权重，可以在指标连续几轮没有改善时停止。<a href="/torch-rechub/zh/tools/callbacks.html">早停与保存</a></li><li><strong>两次训练的曲线有什么区别？</strong> 把损失和验证指标写到本地 TensorBoard 日志，或发到团队使用的 W&amp;B、SwanLab 项目。<a href="/torch-rechub/zh/tools/tracking.html">实验追踪</a></li><li><strong>特征经过了哪些层，形状在哪里变了？</strong> 给模型画一张前向计算图，可以直接在 Jupyter 查看，也可以保存为文件。<a href="/torch-rechub/zh/tools/visualization.html">模型结构图</a></li><li><strong>换模型后指标变了吗？</strong> 用同一份数据和配置跑基准实验，查看两次结果的对比表。<a href="/torch-rechub/zh/tools/benchmark.html">Benchmark</a></li></ul>',4)])])}const m=o(l,[["render",n]]);export{p as __pageData,m as default};
